const $=id=>document.getElementById(id);const modules=['Resumen general','Mis acciones','IDS','Controles críticos','Actos y condiciones','Flash Report'];const icons=['▦','☑','◈','◉','⚑','ϟ'];let current=0;let records;const sample=[['AC-001','Revisar señalización de rutas de evacuación','Ana García','Unidad Norte',-2,'Pendiente','Acciones'],['CC-002','Verificar bloqueo y etiquetado de equipos','Carlos Ruiz','Unidad Norte',3,'Pendiente','Controles críticos'],['IDS-003','Inspección preventiva del área de talleres','Laura Torres','Unidad Centro',5,'Por verificar','IDS'],['AC-004','Reponer protección en tablero eléctrico','Miguel Soto','Unidad Norte',-1,'Pendiente','Actos y condiciones'],['FR-005','Revisión de incidente sin lesión en patio','Ana García','Unidad Centro',7,'Por verificar','Flash Report'],['AC-006','Actualizar identificación de extintores','Carlos Ruiz','Unidad Norte',4,'Cerrado','Acciones']].map(([id,description,owner,unit,days,status,module])=>{let d=new Date();d.setDate(d.getDate()+days);return{id,description,owner,unit,due:localDate(d),status,module,notes:''}});function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}try{const saved=JSON.parse(localStorage.getItem('centinela-v1'));records=Array.isArray(saved)&&saved.every(r=>r&&typeof r.id==='string'&&typeof r.description==='string')?saved:sample}catch{records=sample}function escape(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function state(r){return r.status==='Pendiente'&&r.due<localDate(new Date())?'Vencido':r.status}function save(){try{localStorage.setItem('centinela-v1',JSON.stringify(records));toast('Registro guardado correctamente')}catch{toast('No fue posible guardar en este navegador. Exporta tus registros.')}render()}function toast(t){$('toast').textContent=t;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3500)}$('today').textContent=new Intl.DateTimeFormat('es-MX',{day:'numeric',month:'long',year:'numeric'}).format(new Date()).toUpperCase();$('nav').innerHTML=modules.map((m,i)=>`<button data-page="${i}" class="${i===0?'active':''}"><span>${icons[i]}</span>${m}</button>`).join('');$('nav').onclick=e=>{const b=e.target.closest('button');if(!b)return;current=Number(b.dataset.page);$('search').value='';$('status').value='';$('unit').value='';render()};function filtered(){return records.filter(r=>(current<2||r.module===modules[current])&&(!$('status').value||state(r)===$('status').value)&&(!$('unit').value||r.unit===$('unit').value)&&`${r.id} ${r.description} ${r.owner}`.toLowerCase().includes($('search').value.toLowerCase()))}function render(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',+b.dataset.page===current));$('title').textContent=modules[current];$('breadcrumb').textContent='Espacio de trabajo / '+modules[current];$('subtitle').textContent=current?'Registra hallazgos, asigna responsables y sigue cada compromiso.':'Una visión clara de la seguridad en tu operación.';$('overview').hidden=current!==0;const counts=Object.fromEntries(['Vencido','Pendiente','Por verificar','Cerrado'].map(s=>[s,records.filter(r=>state(r)===s).length]));$('stats').innerHTML=[['Total de acciones',records.length,'Registros de seguridad','▤',''],['Acciones vencidas',counts.Vencido,'Requieren tu atención','◷','red'],['Acciones pendientes',counts.Pendiente,'Dentro del plazo de atención','◴','amber'],['Por verificar',counts['Por verificar'],'En espera de validación','✓','blue']].map(([label,n,sub,icon,c])=>`<div class="stat ${c}"><div class="stat-label">${label}</div><span class="stat-icon">${icon}</span><strong>${String(n).padStart(2,'0')}</strong><small>${sub}</small></div>`).join('');$('openCount').textContent=records.length-counts.Cerrado;const colors=['#cb846e','#dfbe70','#8aa6b8','#80a88b'];let angle=0;const parts=Object.entries(counts).map(([s,n],i)=>{let start=angle;angle+=records.length?n/records.length*100:0;return `${colors[i]} ${start}% ${angle}%`});$('donut').style.background=records.length?`conic-gradient(${parts.join(',')})`:'#eef2eb';$('legend').innerHTML=Object.entries(counts).map(([s,n],i)=>`<div class="legend-row"><i style="background:${colors[i]}"></i>${s}<b>${String(n).padStart(2,'0')}</b></div>`).join('');$('focus').innerHTML=`<div class="focus-row"><span class="focus-icon">!</span><div><b>${counts.Vencido} acciones fuera de plazo</b><p>Revisa los pendientes y actualiza sus avances.</p></div></div><div class="focus-row"><span class="focus-icon" style="background:#eff4e9;color:#8aa27a">✓</span><div><b>${counts['Por verificar']} acciones listas para verificar</b><p>Valida el cumplimiento de las medidas preventivas.</p></div></div>`;$('tableTitle').firstChild.textContent=current>1?'Registros del módulo ':'Seguimiento de acciones ';const list=filtered();$('count').textContent=list.length;$('resultCount').textContent=`Mostrando ${list.length} de ${records.filter(r=>current<2||r.module===modules[current]).length} registros`;$('rows').innerHTML=list.length?list.map(r=>`<tr><td><strong>${escape(r.id)} <span style="color:#a1ad9a;font-weight:400"> · ${escape(r.module)}</span></strong><p title="${escape(r.description)}">${escape(r.description)}</p></td><td><span class="person"><span class="avatar">${escape(r.owner.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span>${escape(r.owner)}</span></td><td>${escape(r.unit)}</td><td>${new Intl.DateTimeFormat('es-MX',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(r.due+'T12:00:00'))}</td><td><span class="badge ${state(r)==='Por verificar'?'verificar':state(r)}">${state(r)}</span></td><td><button class="row-button" data-edit="${escape(r.id)}" aria-label="Abrir ${escape(r.id)}">↗</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No hay registros con estos filtros.</td></tr>'}function openRecord(id){const r=records.find(r=>r.id===id);$('form').reset();$('recordId').value=r?.id||'';$('modalTitle').textContent=r?'Detalle del registro':'Nuevo registro';$('module').value=r?.module||(current>1?modules[current]:'Acciones');$('description').value=r?.description||'';$('owner').value=r?.owner||'';$('recordUnit').value=r?.unit||'Unidad Norte';$('due').value=r?.due||localDate(new Date());$('recordStatus').value=r?.status||'Pendiente';$('notes').value=r?.notes||'';$('modal').showModal()}$('new').onclick=()=>openRecord();$('rows').onclick=e=>{const b=e.target.closest('[data-edit]');if(b)openRecord(b.dataset.edit)};['close','cancel'].forEach(id=>$(id).onclick=()=>$('modal').close());$('form').onsubmit=e=>{e.preventDefault();const id=$('recordId').value||'RG-'+Date.now().toString(36).toUpperCase();const r={id,module:$('module').value,description:$('description').value.trim(),owner:$('owner').value.trim(),unit:$('recordUnit').value,due:$('due').value,status:$('recordStatus').value,notes:$('notes').value.trim()};if(!r.description||!r.owner){toast('Completa la descripción y el responsable.');return}const i=records.findIndex(x=>x.id===id);if(i<0)records.unshift(r);else records[i]=r;save();$('modal').close()};['search','status','unit'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',render));$('clear').onclick=()=>{['search','status','unit'].forEach(id=>$(id).value='');render()};$('viewOverdue').onclick=()=>{current=1;$('status').value='Vencido';render()};$('export').onclick=()=>{const safe=v=>`"${(/^[=+@\-\t\r]/.test(String(v))?"'":'')+String(v).replace(/"/g,'""')}"`;const csv='\uFEFF'+[['Código','Tipo','Descripción','Responsable','Unidad','Fecha límite','Estado','Notas'],...filtered().map(r=>[r.id,r.module,r.description,r.owner,r.unit,r.due,state(r),r.notes])].map(row=>row.map(safe).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download='centinela-registros.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('help').onclick=()=>toast('Demostración local: crea registros, filtra, actualiza estados y exporta CSV.');render();
